CREATE OR REPLACE FUNCTION ai_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF cardinality(NEW.input_evidence_ids)=0 OR EXISTS(SELECT 1 FROM unnest(NEW.input_evidence_ids) AS input(evidence_id) LEFT JOIN raw_evidence r ON r.id=input.evidence_id WHERE r.id IS NULL OR r.raw_content_hash<>encode(sha256(r.raw_content),'hex')) THEN RAISE EXCEPTION 'AI requires intact stored evidence'; END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION entity_profile_review_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.decision='VERIFIED' AND NOT EXISTS(SELECT 1 FROM entity_profile_version p JOIN raw_evidence r ON r.id=p.evidence_id JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE p.id=NEW.profile_id AND s.level='L0' AND l.status='APPROVED' AND l.storage_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND position(p.excerpt IN convert_from(r.raw_content,'UTF8'))>0 AND position(p.original_name IN p.excerpt)>0 AND (p.legal_name IS NULL OR position(p.legal_name IN p.excerpt)>0) AND (p.country IS NULL OR position(p.country IN p.excerpt)>0) AND (p.official_identifier IS NULL OR position(p.official_identifier IN p.excerpt)>0)) THEN RAISE EXCEPTION 'Entity identity review requires intact licensed official proof for all identity fields';END IF;RETURN NEW;END $$;
